/**
 * Correlation ID ownership, generation, and extraction for Sub-Phase 1.6 —
 * Correlation & Request Context.
 *
 * Scope: `docs/phases/PHASE_1_CORE_INFRASTRUCTURE.md` §1.6.
 * Source of truth: `docs/frontend-contract/API_CONTRACT.md` §0.4
 * (optional inbound `X-Correlation-ID`, reused or generated `Guid:N` by the
 * backend, always echoed with `X-Request-ID` in responses).
 *
 * Ownership decision (answers "generated by client, backend, or both"): BOTH,
 * with the client-owned value as the trace key —
 *
 * ```text
 * caller flow id (ApiRequestContext.correlationId)
 *     ↓ wins when supplied: one id traces a whole flow (login → merge → order)
 * per-request UUID (newCorrelationId)
 *     ↓ generated when absent: every request is traceable, never anonymous
 * X-Correlation-ID outbound (correlationInterceptor)
 *     ↓ backend reuses inbound, else generates; always echoes + X-Request-ID
 * normalized ApiError.correlationId (error interceptor: sent → echo → null)
 * ```
 *
 * Plain hyphenated UUIDs are sent (valid backend `Guid`s, echoed verbatim);
 * no format coupling to the backend's internal `Guid:N` rendering. ID
 * lifecycle is out of scope: no storage, rotation, or cancellation handling
 * (1.7 owns lifecycle). SSR-safe: uses only `globalThis.crypto` when
 * available, with a `Math.random` fallback — never `window`/`document`.
 */

import type { HttpHeaders } from '@angular/common/http';

/** Outbound correlation header (also echoed by the backend). */
export const CORRELATION_ID_HEADER = 'X-Correlation-ID';

/** Per-request backend identifier, always generated server-side. */
export const REQUEST_ID_HEADER = 'X-Request-ID';

/**
 * Generates a UUID v4 trace id. Prefers `crypto.randomUUID()`; falls back
 * to a `Math.random` v4 (still unique enough for correlation) where
 * WebCrypto is unavailable.
 */
export function newCorrelationId(): string {
  try {
    const cryptoApi = globalThis.crypto;
    if (cryptoApi && typeof cryptoApi.randomUUID === 'function') {
      return cryptoApi.randomUUID();
    }
  } catch {
    // Fall through to the manual generator below.
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
    const random = Math.floor(Math.random() * 16);
    const value = char === 'x' ? random : (random & 0x3) | 0x8;
    return value.toString(16);
  });
}

/**
 * Reads correlation information from backend response/error headers.
 * Prefers the echoed `X-Correlation-ID` (== the sent id in practice),
 * falls back to the backend-generated `X-Request-ID`, else `null`.
 */
export function extractCorrelationId(headers: HttpHeaders | null | undefined): string | null {
  if (!headers) {
    return null;
  }
  return headers.get(CORRELATION_ID_HEADER) ?? headers.get(REQUEST_ID_HEADER);
}
